# Generated by build.py from recipe.yml for recipe smtp-route-mail-through-aliases. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'help.eml'), "From: app@example.com`nTo: support@example.com`nSubject: Cannot log in`n`nPlease reset my password.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'alert.eml'), "From: app@example.com`nTo: alerts@example.com`nSubject: Disk full`n`nDisk 2 is nearly full.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'forwarded.eml'), "From: app@example.com`nTo: help@example.com`nSubject: Forwarded twice`n`nThis went to help@.`n")
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--mailbox', 'bob@example.com:bobpass', '--mailbox', 'ops@example.com:opspass', '--mail-alias', '"support@example.com=ann@example.com,bob@example.com"', '--mail-alias', '"alerts@example.com=ops@example.com"', '--mail-alias', '"help@example.com=support@example.com"', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt support@example.com -T help.eml smtp://127.0.0.1:8080/example.com --next --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt alerts@example.com -T alert.eml smtp://127.0.0.1:8080/example.com
try { curl.exe -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Cannot%20log%20in%22" --next -u bob@example.com:bobpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Cannot%20log%20in%22" --next -u ops@example.com:opspass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Disk%20full%22" } finally { Stop-Process $server0 }
